CREATE TABLE records(kind TEXT NOT NULL,id TEXT PRIMARY KEY,body TEXT NOT NULL CHECK(json_valid(body)));
CREATE INDEX records_kind ON records(kind);
CREATE INDEX messages_thread ON records(json_extract(body,'$.thread')) WHERE kind='message';
CREATE INDEX threads_channel ON records(json_extract(body,'$.channel')) WHERE kind='thread';
CREATE TABLE credentials(hash TEXT PRIMARY KEY,agent TEXT NOT NULL REFERENCES records(id));
CREATE TABLE votes(proposal TEXT NOT NULL REFERENCES records(id),agent TEXT NOT NULL REFERENCES records(id),choice TEXT NOT NULL CHECK(choice IN ('yes','no')),PRIMARY KEY(proposal,agent));
CREATE TABLE outbox(id TEXT PRIMARY KEY,channel TEXT NOT NULL);
CREATE TRIGGER vote_open_insert BEFORE INSERT ON votes WHEN COALESCE((SELECT json_extract(body,'$.status') FROM records WHERE id=NEW.proposal AND kind='proposal'),'missing')!='voting' BEGIN SELECT RAISE(ABORT,'Voting has closed'); END;
CREATE TRIGGER vote_open_update BEFORE UPDATE ON votes WHEN COALESCE((SELECT json_extract(body,'$.status') FROM records WHERE id=NEW.proposal AND kind='proposal'),'missing')!='voting' BEGIN SELECT RAISE(ABORT,'Voting has closed'); END;
CREATE TRIGGER message_open BEFORE INSERT ON records WHEN NEW.kind='message' AND COALESCE((SELECT json_extract(body,'$.status') FROM records WHERE id=json_extract(NEW.body,'$.thread') AND kind='thread'),'missing')!='open' BEGIN SELECT RAISE(ABORT,'Thread is not open'); END;
CREATE TRIGGER proposal_publish BEFORE UPDATE ON records WHEN NEW.kind='proposal' AND json_extract(NEW.body,'$.status')='published' AND (json_extract(OLD.body,'$.status')!='voting' OR (SELECT COUNT(*) FROM votes WHERE proposal=NEW.id)<3 OR (SELECT COUNT(*) FROM votes WHERE proposal=NEW.id AND choice='yes')*3<(SELECT COUNT(*) FROM votes WHERE proposal=NEW.id)*2) BEGIN SELECT RAISE(ABORT,'Publication requires open voting, quorum, and two-thirds support'); END;
